begin;
update public.operation_family_rules set plan_scope=jsonb_set(plan_scope,'{trainTypes}',(plan_scope->'trainTypes')||'["AirportRapid"]'::jsonb) where network_key='TokyoMonorail' and code_pattern='PLAN:REMAIN-35' and effective_from=date '2026-10-16' and not (plan_scope->'trainTypes' ? 'AirportRapid');
update public.operation_family_rules set plan_scope=jsonb_set(plan_scope,'{trainTypes}',(plan_scope->'trainTypes')||'["CommuterLimitedExpress"]'::jsonb) where network_key='TokyuToyoko' and code_pattern='PLAN:OWN-TokyuToyoko' and effective_from=date '2026-10-16' and not (plan_scope->'trainTypes' ? 'CommuterLimitedExpress');
commit;